import React, { useState, useEffect, useCallback } from 'react';
import { NAV_SECTIONS, INITIAL_STATE, NEW_EXPERIENCE_ITEM, NEW_EDUCATION_ITEM, NEW_CERTIFICATION_ITEM, NEW_LANGUAGE_ITEM, NEW_PROJECT_ITEM, NEW_AWARD_ITEM, NEW_TRAINING_ITEM, NEW_PUBLICATION_ITEM, NEW_VOLUNTEER_ITEM, NEW_CUSTOM_ITEM } from '../constants';
import type { ResumeData, SectionId, TemplateId, AIAnalysisResult, ResumeSettings } from '../types';
import NavSidebar from './NavSidebar';
import HeaderActions from './HeaderActions';
import ContactForm from './forms/ContactForm';
import SummaryForm from './forms/SummaryForm';
import ExperienceForm from './forms/ExperienceForm';
import ProjectsForm from './forms/ProjectsForm';
import EducationForm from './forms/EducationForm';
import SkillsForm from './forms/SkillsForm';
import CertificationsForm from './forms/CertificationsForm';
import LanguagesForm from './forms/LanguagesForm';
import FinalizeForm from './forms/FinalizeForm';
import AIActionModal from './AIActionModal';
import { exampleData } from '../exampleData';
import AtsChecker from './AtsChecker';
import AwardsForm from './forms/AwardsForm';
import TrainingsForm from './forms/TrainingsForm';
import PublicationsForm from './forms/PublicationsForm';
import VolunteerForm from './forms/VolunteerForm';
import CustomSectionForm from './forms/CustomSectionForm';
import CustomizeForm from './forms/CustomizeForm';

declare global {
    interface Window {
        html2pdf: any;
    }
}

const loadState = (): ResumeData => {
    try {
        const serializedState = localStorage.getItem('cvleap-resume-data');
        if (serializedState === null) {
            return INITIAL_STATE;
        }
        const parsed = JSON.parse(serializedState);
        return { ...INITIAL_STATE, ...parsed };
    } catch (err) {
        console.error("Could not load state from local storage", err);
        return INITIAL_STATE;
    }
};

const loadVisibleSections = (): SectionId[] => {
    try {
        const serialized = localStorage.getItem('cvleap-visible-sections');
        if (serialized) return JSON.parse(serialized);
    } catch (e) {}
    // Default commonly used sections
    return ['certifications', 'languages'];
}

const INITIAL_SETTINGS: ResumeSettings = {
    themeColor: '#008080',
    fontSize: 'medium',
    fontFamily: 'Arial, sans-serif'
};

interface ResumeBuilderProps {
    onBack: () => void;
}

const ResumeBuilder: React.FC<ResumeBuilderProps> = ({ onBack }) => {
    const [activeSection, setActiveSection] = useState<SectionId>(NAV_SECTIONS[0].id);
    const [formData, setFormData] = useState<ResumeData>(loadState);
    const [visibleSections, setVisibleSections] = useState<SectionId[]>(loadVisibleSections);
    const [settings, setSettings] = useState<ResumeSettings>(INITIAL_SETTINGS);
    const [progress, setProgress] = useState(0);
    const [isAiActionModalOpen, setIsAiActionModalOpen] = useState(false);
    const [isAtsModalOpen, setIsAtsModalOpen] = useState(false);
    const [selectedTemplate, setSelectedTemplate] = useState<TemplateId>('default');
    const [saveState, setSaveState] = useState<'idle' | 'saving' | 'saved'>('idle');
    const [isGeneratingPDF, setIsGeneratingPDF] = useState(false);

    useEffect(() => {
        setSaveState('saving');
        try {
            const serializedState = JSON.stringify(formData);
            localStorage.setItem('cvleap-resume-data', serializedState);

            const timer = setTimeout(() => {
                setSaveState('saved');
                const resetTimer = setTimeout(() => setSaveState('idle'), 1500);
                return () => clearTimeout(resetTimer);
            }, 300);
             return () => clearTimeout(timer);
        } catch (err) {
            console.error("Could not save state to local storage", err);
            setSaveState('idle');
        }
    }, [formData]);

    useEffect(() => {
        localStorage.setItem('cvleap-visible-sections', JSON.stringify(visibleSections));
    }, [visibleSections]);

    const handleLoadExample = useCallback(() => {
        if (window.confirm("Are you sure you want to load the example data? This will overwrite your current progress.")) {
            setFormData(exampleData);
            // Ensure commonly used sections from example data are visible
            const newVisible = new Set(visibleSections);
            if (exampleData.projects.length > 0) newVisible.add('projects');
            if (exampleData.languages.length > 0) newVisible.add('languages');
            if (exampleData.certifications.length > 0) newVisible.add('certifications');
            setVisibleSections(Array.from(newVisible));
        }
    }, [visibleSections]);

    const handleSaveDraft = useCallback(() => {
        try {
            const serializedState = JSON.stringify(formData);
            localStorage.setItem('cvleap-resume-data', serializedState);
        } catch (err) {
            console.error("Could not save draft to local storage", err);
        }
    }, [formData]);

    const handleApplyAiSuggestions = (suggestions: AIAnalysisResult) => {
        setFormData(prev => {
            const newData = { ...prev };

            if (suggestions.summarySuggestion) {
                newData.summary.professionalSummary = suggestions.summarySuggestion;
            }

            if (suggestions.experienceSuggestions) {
                newData.experience = newData.experience.map(exp => {
                    const suggestionForExp = suggestions.experienceSuggestions?.find(s => s.id === exp.id);
                    if (suggestionForExp) {
                        return { ...exp, description: suggestionForExp.improvedDescription };
                    }
                    return exp;
                });
            }

            if (suggestions.missingKeywords) {
                const currentSkillsLower = new Set(newData.skills.map(s => s.toLowerCase()));
                const skillsToAdd = suggestions.missingKeywords.filter(k => !currentSkillsLower.has(k.toLowerCase()));
                newData.skills = [...newData.skills, ...skillsToAdd];
            }

            return newData;
        });
    };

    const handlePhotoChange = useCallback((photoData: string) => {
        setFormData(prev => ({
            ...prev,
            contact: {
                ...prev.contact,
                photo: photoData
            }
        }));
    }, []);

    const handleListChange = useCallback((section: 'experience' | 'projects' | 'education' | 'certifications' | 'languages' | 'awards' | 'trainings' | 'publications' | 'volunteer' | 'custom', id: string, e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
        const { name, value } = e.target;
        setFormData(prev => {
            // @ts-ignore 
            const list = prev[section].map((item: any) =>
                item.id === id ? { ...item, [name]: value } : item
            );
            return { ...prev, [section]: list };
        });
    }, []);

    const handleAddItem = useCallback((section: 'experience' | 'projects' | 'education' | 'certifications' | 'languages' | 'awards' | 'trainings' | 'publications' | 'volunteer' | 'custom') => {
        let newItem;
        const id = crypto.randomUUID();
        if (section === 'experience') newItem = { ...NEW_EXPERIENCE_ITEM, id };
        else if (section === 'projects') newItem = { ...NEW_PROJECT_ITEM, id };
        else if (section === 'education') newItem = { ...NEW_EDUCATION_ITEM, id };
        else if (section === 'certifications') newItem = { ...NEW_CERTIFICATION_ITEM, id };
        else if (section === 'languages') newItem = { ...NEW_LANGUAGE_ITEM, id };
        else if (section === 'awards') newItem = { ...NEW_AWARD_ITEM, id };
        else if (section === 'trainings') newItem = { ...NEW_TRAINING_ITEM, id };
        else if (section === 'publications') newItem = { ...NEW_PUBLICATION_ITEM, id };
        else if (section === 'volunteer') newItem = { ...NEW_VOLUNTEER_ITEM, id };
        else if (section === 'custom') newItem = { ...NEW_CUSTOM_ITEM, id };

        if (newItem) {
            setFormData(prev => ({
                ...prev,
                // @ts-ignore
                [section]: [...(prev[section] || []), newItem]
            }));
        }
    }, []);

    const handleRemoveItem = useCallback((section: 'experience' | 'projects' | 'education' | 'certifications' | 'languages' | 'awards' | 'trainings' | 'publications' | 'volunteer' | 'custom', id: string) => {
        setFormData(prev => ({
            ...prev,
             // @ts-ignore
            [section]: (prev[section] || []).filter((item: any) => item.id !== id)
        }));
    }, []);

    const handleSkillAdd = useCallback((skill: string) => {
        if (!formData.skills.includes(skill)) {
            setFormData(prev => ({
                ...prev,
                skills: [...prev.skills, skill]
            }));
        }
    }, [formData.skills]);

    const handleSkillRemove = useCallback((index: number) => {
        setFormData(prev => ({
            ...prev,
            skills: prev.skills.filter((_, i) => i !== index)
        }));
    }, []);

    const handleClearSection = useCallback(() => {
        setFormData(prev => ({
            ...prev,
            [activeSection]: INITIAL_STATE[activeSection]
        }));
    }, [activeSection]);

    const handleNextSection = useCallback(() => {
        const currentNav = NAV_SECTIONS.filter(s => !s.optional || visibleSections.includes(s.id));
        const currentIndex = currentNav.findIndex(s => s.id === activeSection);

        if (currentIndex < currentNav.length - 1) {
            setActiveSection(currentNav[currentIndex + 1].id);
        }
    }, [activeSection, visibleSections]);

    const handleToggleSection = (section: SectionId) => {
        setVisibleSections(prev => {
            if (prev.includes(section)) {
                return prev.filter(s => s !== section);
            } else {
                return [...prev, section];
            }
        });
    };

    const handleDownloadPDF = useCallback(async () => {
        console.log("📄 Starting PDF generation flow...");
        setIsGeneratingPDF(true); // Show overlay

        // Delay to allow the "Generating PDF..." overlay to render and cover the screen
        await new Promise(resolve => setTimeout(resolve, 200));

        const wrapper = document.getElementById('resume-preview-wrapper');
        const originalElement = wrapper?.firstElementChild as HTMLElement;

        if (!originalElement) {
            console.error("❌ Resume preview element not found in DOM");
            setIsGeneratingPDF(false);
            return;
        }

        console.log("✅ Resume source element detected. Preparing clone for capture...");

        // Clone the element for processing
        const clone = originalElement.cloneNode(true) as HTMLElement;

        // CRITICAL FIX FOR BLANK PAGE:
        // Position the clone at (0,0) in the viewport. 
        // We use position: fixed to ensure its coordinates are predictable for html2canvas.
        // We give it a high z-index (8000) so it's above the app content but BELOW our loading overlay (9999).
        // This ensures the capture engine sees it perfectly without it being visible to the user.
        Object.assign(clone.style, {
            position: 'fixed',
            left: '0',
            top: '0',
            width: '794px', // Standard A4 width in pixels at 96 DPI
            minHeight: '1123px', // Standard A4 height
            height: 'auto',
            zIndex: '8000',
            backgroundColor: '#ffffff',
            margin: '0',
            transform: 'none', // Remove any scaling/transforms from the sidebar
            overflow: 'visible',
            boxShadow: 'none',
            border: 'none',
            opacity: '1',
            visibility: 'visible'
        });

        // Strip any classes that might cause scaling or absolute offsets from parent containers
        clone.className = clone.className.replace(/\b(scale|origin|absolute|pointer-events)\S+/g, '');

        // Append to body to make it renderable
        document.body.appendChild(clone);
        console.log("✅ Clone injected into document body.");

        // Wait significantly for layout recalculation, images (like headshot), and fonts to fully paint
        await new Promise(resolve => setTimeout(resolve, 1500));

        const year = new Date().getFullYear();
        const firstName = formData.contact.firstName || 'My';
        const lastName = formData.contact.lastName || 'Resume';
        const jobTitle = (formData.contact.jobTitle || 'CV').replace(/[\s/|]+/g, '_');
        const filename = `${firstName}_${lastName}_${jobTitle}_${year}.pdf`;

        console.log(`🖨️ Generating PDF: ${filename}`);

        const opt = {
            margin: 0,
            filename: filename,
            image: { type: 'jpeg', quality: 0.98 },
            html2canvas: { 
                scale: 2, 
                useCORS: true, 
                allowTaint: true,
                letterRendering: true,
                scrollY: 0,
                scrollX: 0,
                windowWidth: 794,
                width: 794,
                logging: true // Keep logging enabled to debug in console if blank issues return
            },
            jsPDF: { 
                unit: 'px', 
                format: [794, 1123], 
                orientation: 'portrait',
                hotfixes: ['px_scaling']
            }
        };

        try {
            // We capture from the specifically positioned and sized clone
            await window.html2pdf().set(opt).from(clone).save();
            console.log("✅ PDF generation complete and download triggered.");
        } catch (error) {
            console.error("❌ PDF engine error:", error);
        } finally {
            // Clean up the temporary element
            if (document.body.contains(clone)) {
                document.body.removeChild(clone);
                console.log("🧹 Clone removed from DOM.");
            }
            setIsGeneratingPDF(false); // Hide the overlay
        }
    }, [formData]);

    useEffect(() => {
        let filledFields = 0;
        let totalFields = 5;

        if (formData.contact.firstName) filledFields++;
        if (formData.contact.lastName) filledFields++;
        if (formData.contact.jobTitle) filledFields++;
        if (formData.contact.email) filledFields++;
        if (formData.contact.phone) filledFields++;

        if (formData.summary.professionalSummary) filledFields++; totalFields++;
        if (formData.experience.length > 0) filledFields++; totalFields++;
        if (formData.education.length > 0) filledFields++; totalFields++;
        if (formData.skills.length > 0) filledFields++; totalFields++;

        if (visibleSections.includes('projects') && formData.projects && formData.projects.length > 0) { filledFields++; totalFields++; }
        if (visibleSections.includes('certifications') && formData.certifications.length > 0) { filledFields++; totalFields++; }
        if (visibleSections.includes('languages') && formData.languages && formData.languages.length > 0) { filledFields++; totalFields++; }
        if (visibleSections.includes('awards') && formData.awards && formData.awards.length > 0) { filledFields++; totalFields++; }
        if (visibleSections.includes('trainings') && formData.trainings && formData.trainings.length > 0) { filledFields++; totalFields++; }
        if (visibleSections.includes('publications') && formData.publications && formData.publications.length > 0) { filledFields++; totalFields++; }
        if (visibleSections.includes('volunteer') && formData.volunteer && formData.volunteer.length > 0) { filledFields++; totalFields++; }
        if (visibleSections.includes('custom') && formData.custom && formData.custom.length > 0) { filledFields++; totalFields++; }

        setProgress(Math.round((filledFields / totalFields) * 100));
    }, [formData, visibleSections]);

    const renderActiveForm = () => {
        switch (activeSection) {
            case 'contact':
                return <ContactForm data={formData.contact} onFormDataChange={setFormData} onPhotoChange={handlePhotoChange} onClear={handleClearSection} onNext={handleNextSection} />;
            case 'summary':
                return <SummaryForm data={formData} onFormDataChange={setFormData} onClear={handleClearSection} onNext={handleNextSection} />;
            case 'experience':
                return <ExperienceForm data={formData.experience} onFormDataChange={setFormData} onAdd={() => handleAddItem('experience')} onRemove={(id) => handleRemoveItem('experience', id)} onClear={handleClearSection} onNext={handleNextSection} />;
            case 'projects':
                return <ProjectsForm data={formData.projects} onChange={(id, e) => handleListChange('projects', id, e)} onAdd={() => handleAddItem('projects')} onRemove={(id) => handleRemoveItem('projects', id)} onClear={handleClearSection} onNext={handleNextSection} />;
            case 'education':
                return <EducationForm data={formData.education} onChange={(id, e) => handleListChange('education', id, e)} onAdd={() => handleAddItem('education')} onRemove={(id) => handleRemoveItem('education', id)} onClear={handleClearSection} onNext={handleNextSection} />;
            case 'skills':
                return <SkillsForm skills={formData.skills} jobTitle={formData.contact.jobTitle} onAdd={handleSkillAdd} onRemove={handleSkillRemove} onClear={handleClearSection} onNext={handleNextSection} />;
            case 'certifications':
                return <CertificationsForm data={formData.certifications} onChange={(id, e) => handleListChange('certifications', id, e)} onAdd={() => handleAddItem('certifications')} onRemove={(id) => handleRemoveItem('certifications', id)} onClear={handleClearSection} onNext={handleNextSection} />;
            case 'languages':
                return <LanguagesForm data={formData.languages} onChange={(id, e) => handleListChange('languages', id, e)} onAdd={() => handleAddItem('languages')} onRemove={(id) => handleRemoveItem('languages', id)} onClear={handleClearSection} onNext={handleNextSection} />;
            case 'awards':
                return <AwardsForm data={formData.awards} onChange={(id, e) => handleListChange('awards', id, e)} onAdd={() => handleAddItem('awards')} onRemove={(id) => handleRemoveItem('awards', id)} onClear={handleClearSection} onNext={handleNextSection} />;
            case 'trainings':
                return <TrainingsForm data={formData.trainings} onChange={(id, e) => handleListChange('trainings', id, e)} onAdd={() => handleAddItem('trainings')} onRemove={(id) => handleRemoveItem('trainings', id)} onClear={handleClearSection} onNext={handleNextSection} />;
            case 'publications':
                return <PublicationsForm data={formData.publications} onChange={(id, e) => handleListChange('publications', id, e)} onAdd={() => handleAddItem('publications')} onRemove={(id) => handleRemoveItem('publications', id)} onClear={handleClearSection} onNext={handleNextSection} />;
            case 'volunteer':
                return <VolunteerForm data={formData.volunteer} onChange={(id, e) => handleListChange('volunteer', id, e)} onAdd={() => handleAddItem('volunteer')} onRemove={(id) => handleRemoveItem('volunteer', id)} onClear={handleClearSection} onNext={handleNextSection} />;
            case 'custom':
                return <CustomSectionForm data={formData.custom} onChange={(id, e) => handleListChange('custom', id, e)} onAdd={() => handleAddItem('custom')} onRemove={(id) => handleRemoveItem('custom', id)} onClear={handleClearSection} onNext={handleNextSection} />;
            case 'customize':
                return <CustomizeForm visibleSections={visibleSections} onToggleSection={handleToggleSection} />;
            case 'finalize':
                return <FinalizeForm 
                    onDownloadPDF={handleDownloadPDF} 
                    selectedTemplate={selectedTemplate} 
                    onTemplateChange={setSelectedTemplate} 
                    formData={formData} 
                    onOpenAtsModal={() => setIsAtsModalOpen(true)} 
                    visibleSections={visibleSections}
                    settings={settings}
                    onSettingsChange={setSettings}
                />;
            default:
                return null;
        }
    };

    return (
        <div className="flex h-screen bg-transparent overflow-hidden">
            <NavSidebar
                activeSection={activeSection}
                onSectionClick={setActiveSection}
                progress={progress}
                formData={formData}
                onDownloadPDF={handleDownloadPDF}
                selectedTemplate={selectedTemplate}
                visibleSections={visibleSections}
                settings={settings}
                onGoHome={onBack}
            />
            {/* Main Content Area - Shifted Right */}
            <main className="flex-1 ml-[400px] h-full overflow-y-auto bg-light/50 relative">
                <div className="max-w-5xl mx-auto p-10 min-h-screen">
                    <div className="glass-panel p-8 rounded-3xl min-h-[calc(100vh-5rem)] border border-white/40 shadow-xl bg-white/60 backdrop-blur-md">
                        <HeaderActions
                            onAiEnhanceClick={() => setIsAiActionModalOpen(true)}
                            onLoadExample={handleLoadExample}
                            saveState={saveState}
                            onSaveDraft={handleSaveDraft}
                        />
                        <div className="animate-fade-in mt-6">
                            {renderActiveForm()}
                        </div>
                    </div>
                </div>
            </main>

            {/* Full Screen Loading Overlay for PDF Generation - Very high z-index */}
            {isGeneratingPDF && (
                <div className="fixed inset-0 z-[9999] bg-white/95 backdrop-blur-sm flex flex-col items-center justify-center">
                    <div className="w-16 h-16 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
                    <h2 className="text-2xl font-bold text-primary">Creating High-Quality PDF...</h2>
                    <p className="text-gray-500 mt-2">Finalizing layout and optimizing fonts</p>
                </div>
            )}

            <AIActionModal
                isOpen={isAiActionModalOpen}
                onClose={() => setIsAiActionModalOpen(false)}
                resumeData={formData}
                activeSection={activeSection}
                onApplySuggestions={handleApplyAiSuggestions}
            />
             <AtsChecker
                isOpen={isAtsModalOpen}
                onClose={() => setIsAtsModalOpen(false)}
                resumeData={formData}
            />
        </div>
    );
}

export default ResumeBuilder;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { NAV_SECTIONS, INITIAL_STATE, NEW_EXPERIENCE_ITEM, NEW_EDUCATION_ITEM, NEW_CERTIFICATION_ITEM, NEW_LANGUAGE_ITEM, NEW_PROJECT_ITEM, NEW_AWARD_ITEM, NEW_TRAINING_ITEM, NEW_PUBLICATION_ITEM, NEW_VOLUNTEER_ITEM, NEW_CUSTOM_ITEM } from '../constants';
import type { ResumeData, SectionId, TemplateId, AIAnalysisResult, ResumeSettings } from '../types';
import NavSidebar from './NavSidebar';
import HeaderActions from './HeaderActions';
import ContactForm from './forms/ContactForm';
import SummaryForm from './forms/SummaryForm';
