        else if (section === 'publications') newItem = { ...NEW_PUBLICATION_ITEM, id };
        else if (section === 'volunteer') newItem = { ...NEW_VOLUNTEER_ITEM, id };
        else if (section === 'custom') newItem = { ...NEW_CUSTOM_ITEM, id };

        if (newItem) {
            setFormData(prev => ({ ...prev, [section]: [...((prev as any)[section] || []), newItem] }));
        }
    }, []);

    const handleRemoveItem = useCallback((section: any, id: string) => {
        setFormData(prev => ({ ...prev, [section]: ((prev as any)[section] || []).filter((item: any) => item.id !== id) }));
    }, []);

    const handleSkillAdd = useCallback((skill: string) => {
        if (!formData.skills.includes(skill)) {
            setFormData(prev => ({ ...prev, skills: [...prev.skills, skill] }));
        }
    }, [formData.skills]);

    const handleSkillRemove = useCallback((index: number) => {
        setFormData(prev => ({ ...prev, skills: prev.skills.filter((_, i) => i !== index) }));
    }, []);

    const handleClearSection = useCallback(() => {
        setFormData(prev => ({ ...prev, [activeSection]: (INITIAL_STATE as any)[activeSection] }));
    }, [activeSection]);

    const handleNextSection = useCallback(() => {
        const currentNav = NAV_SECTIONS.filter(s => !s.optional || visibleSections.includes(s.id));
        const currentIndex = currentNav.findIndex(s => s.id === activeSection);
        if (currentIndex < currentNav.length - 1) setActiveSection(currentNav[currentIndex + 1].id);
    }, [activeSection, visibleSections]);

    const handleToggleSection = (section: SectionId) => {
        setVisibleSections(prev => prev.includes(section) ? prev.filter(s => s !== section) : [...prev, section]);
    };

    const handleDownloadPDF = useCallback(async () => {
        console.log("📄 PDF download requested...");
        setIsGeneratingPDF(true);

        // Ensure the overlay is rendered
        await new Promise(resolve => setTimeout(resolve, 500));

        const element = document.getElementById('capture-root');
        if (!element) {
            console.error("❌ Capture element not found");
            setIsGeneratingPDF(false);
            return;
        }

        const year = new Date().getFullYear();
        const firstName = formData.contact.firstName || 'My';
        const lastName = formData.contact.lastName || 'Resume';
        const jobTitle = (formData.contact.jobTitle || 'CV').replace(/[\s/|]+/g, '_');
        const filename = `${firstName}_${lastName}_${jobTitle}_${year}.pdf`;

        const opt = {
            margin: 0,
            filename: filename,
            image: { type: 'jpeg', quality: 0.98 },
            html2canvas: { 
                scale: 2, 
                useCORS: true,
                letterRendering: true,
                logging: false,
                backgroundColor: '#ffffff'
            },
            // CRITICAL FOR PAGE BREAKS
            pagebreak: { 
                mode: ['avoid-all', 'css', 'legacy']
            },
            jsPDF: { 
                unit: 'mm', 
                format: 'a4', 
                orientation: 'portrait' 
            }
        };

        try {
            await window.html2pdf().set(opt).from(element).save();
            console.log("✅ PDF Download successful");
        } catch (error) {
            console.error("❌ PDF Engine Error:", error);
            alert("There was an error generating your PDF. Please try again.");
        } finally {
            setIsGeneratingPDF(false);
        }
    }, [formData]);

    useEffect(() => {
        let filledFields = 0;
        let totalFields = 5;
        if (formData.contact.firstName) filledFields++;
        if (formData.contact.lastName) filledFields++;
        if (formData.contact.jobTitle) filledFields++;
        if (formData.contact.email) filledFields++;
        if (formData.contact.phone) filledFields++;
        if (formData.summary.professionalSummary) filledFields++; totalFields++;
        if (formData.experience.length > 0) filledFields++; totalFields++;
        if (formData.education.length > 0) filledFields++; totalFields++;
        if (formData.skills.length > 0) filledFields++; totalFields++;
        setProgress(Math.round((filledFields / totalFields) * 100));
    }, [formData, visibleSections]);

    const CaptureTemplate = useMemo(() => {
        const Component = templateMap[selectedTemplate] || ResumePreview;
        return <Component formData={formData} isCardPreview={false} visibleSections={visibleSections} settings={settings} />;
    }, [selectedTemplate, formData, visibleSections, settings]);

    const renderActiveForm = () => {
        switch (activeSection) {
            case 'contact': return <ContactForm data={formData.contact} onFormDataChange={setFormData} onPhotoChange={handlePhotoChange} onClear={handleClearSection} onNext={handleNextSection} />;
            case 'summary': return <SummaryForm data={formData} onFormDataChange={setFormData} onClear={handleClearSection} onNext={handleNextSection} />;
            case 'experience': return <ExperienceForm data={formData.experience} onFormDataChange={setFormData} onAdd={() => handleAddItem('experience')} onRemove={(id) => handleRemoveItem('experience', id)} onClear={handleClearSection} onNext={handleNextSection} />;
            case 'projects': return <ProjectsForm data={formData.projects} onChange={(id, e) => handleListChange('projects', id, e)} onAdd={() => handleAddItem('projects')} onRemove={(id) => handleRemoveItem('projects', id)} onClear={handleClearSection} onNext={handleNextSection} />;
            case 'education': return <EducationForm data={formData.education} onChange={(id, e) => handleListChange('education', id, e)} onAdd={() => handleAddItem('education')} onRemove={(id) => handleRemoveItem('education', id)} onClear={handleClearSection} onNext={handleNextSection} />;
            case 'skills': return <SkillsForm skills={formData.skills} jobTitle={formData.contact.jobTitle} onAdd={handleSkillAdd} onRemove={handleSkillRemove} onClear={handleClearSection} onNext={handleNextSection} />;
            case 'certifications': return <CertificationsForm data={formData.certifications} onChange={(id, e) => handleListChange('certifications', id, e)} onAdd={() => handleAddItem('certifications')} onRemove={(id) => handleRemoveItem('certifications', id)} onClear={handleClearSection} onNext={handleNextSection} />;
            case 'languages': return <LanguagesForm data={formData.languages} onChange={(id, e) => handleListChange('languages', id, e)} onAdd={() => handleAddItem('languages')} onRemove={(id) => handleRemoveItem('languages', id)} onClear={handleClearSection} onNext={handleNextSection} />;
            case 'awards': return <AwardsForm data={formData.awards} onChange={(id, e) => handleListChange('awards', id, e)} onAdd={() => handleAddItem('awards')} onRemove={(id) => handleRemoveItem('awards', id)} onClear={handleClearSection} onNext={handleNextSection} />;
            case 'trainings': return <TrainingsForm data={formData.trainings} onChange={(id, e) => handleListChange('trainings', id, e)} onAdd={() => handleAddItem('trainings')} onRemove={(id) => handleRemoveItem('trainings', id)} onClear={handleClearSection} onNext={handleNextSection} />;
            case 'publications': return <PublicationsForm data={formData.publications} onChange={(id, e) => handleListChange('publications', id, e)} onAdd={() => handleAddItem('publications')} onRemove={(id) => handleRemoveItem('publications', id)} onClear={handleClearSection} onNext={handleNextSection} />;
            case 'volunteer': return <VolunteerForm data={formData.volunteer} onChange={(id, e) => handleListChange('volunteer', id, e)} onAdd={() => handleAddItem('volunteer')} onRemove={(id) => handleRemoveItem('volunteer', id)} onClear={handleClearSection} onNext={handleNextSection} />;
            case 'custom': return <CustomSectionForm data={formData.custom} onChange={(id, e) => handleListChange('custom', id, e)} onAdd={() => handleAddItem('custom')} onRemove={(id) => handleRemoveItem('custom', id)} onClear={handleClearSection} onNext={handleNextSection} />;
            case 'customize': return <CustomizeForm visibleSections={visibleSections} onToggleSection={handleToggleSection} />;
            case 'finalize': return <FinalizeForm onDownloadPDF={handleDownloadPDF} selectedTemplate={selectedTemplate} onTemplateChange={setSelectedTemplate} formData={formData} onOpenAtsModal={() => setIsAtsModalOpen(true)} visibleSections={visibleSections} settings={settings} onSettingsChange={setSettings} />;
            default: return null;
        }
    };

    return (
        <div className="flex h-screen bg-transparent overflow-hidden">
            <NavSidebar
                activeSection={activeSection}
                onSectionClick={setActiveSection}
                progress={progress}
                formData={formData}
                onDownloadPDF={handleDownloadPDF}
                selectedTemplate={selectedTemplate}
                visibleSections={visibleSections}
                settings={settings}
                onGoHome={onBack}
            />
            <main className="flex-1 ml-[400px] h-full overflow-y-auto bg-light/50 relative">
                <div className="max-w-5xl mx-auto p-10 min-h-screen">
                    <div className="glass-panel p-8 rounded-3xl min-h-[calc(100vh-5rem)] border border-white/40 shadow-xl bg-white/60 backdrop-blur-md">
                        <HeaderActions
                            onAiEnhanceClick={() => setIsAiActionModalOpen(true)}
                            onLoadExample={handleLoadExample}
                            saveState={saveState}
                            onSaveDraft={handleSaveDraft}
                        />
                        <div className="animate-fade-in mt-6">
                            {renderActiveForm()}
                        </div>
                    </div>
                </div>
            </main>

            {/* Hidden High-Quality Capture Area - Visible to DOM but moved far off-screen */}
            <div 
                className="fixed top-0 pointer-events-none" 
                style={{ left: '-9999px', width: '794px', visibility: 'visible', opacity: 1, zIndex: -1000 }}
            >
                <div id="capture-root" className="bg-white">
                    {CaptureTemplate}
                </div>
            </div>

            {isGeneratingPDF && (
                <div className="fixed inset-0 z-[10000] bg-white/95 backdrop-blur-sm flex flex-col items-center justify-center">
                    <div className="w-16 h-16 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
                    <h2 className="text-2xl font-bold text-primary">Preparing your PDF...</h2>
                    <p className="text-gray-500 mt-2">Optimizing layout and fonts for high quality</p>
                </div>
            )}

            <AIActionModal
                isOpen={isAiActionModalOpen}
                onClose={() => setIsAiActionModalOpen(false)}
                resumeData={formData}
                activeSection={activeSection}
                onApplySuggestions={handleApplyAiSuggestions}
            />
             <AtsChecker
                isOpen={isAtsModalOpen}
                onClose={() => setIsAtsModalOpen(false)}
                resumeData={formData}
            />
        </div>
    );
}

export default ResumeBuilder;

import React, { useEffect, useMemo, useState, useCallback } from 'react';
import { useEditor, EditorContent } from '@tiptap/react';
import StarterKit from '@tiptap/starter-kit';
import Placeholder from '@tiptap/extension-placeholder';
import Underline from '@tiptap/extension-underline';
import ListKeymap from '@tiptap/extension-list-keymap';
import type { Experience, ResumeData } from '../../types';
import ContentHeader from '../common/ContentHeader';
import FormActions from '../common/FormActions';
import { generateBulletPointSuggestions } from '../../services/geminiService';
import { SparklesIcon, BoldIcon, ItalicIcon, UnderlineIcon, ListBulletIcon, ListNumberedIcon } from '../common/icons';

interface ExperienceFormProps {
  data: Experience[];
  onAdd: () => void;
  onRemove: (id: string) => void;
  onClear: () => void;
  onNext: () => void;
  onFormDataChange: React.Dispatch<React.SetStateAction<ResumeData>>;
}

const BulletEditor = React.memo(({ html, onUpdate }: {
  html: string;
  onUpdate: (html: string) => void;
}) => {
  const editor = useEditor({
    extensions: [
      StarterKit.configure({
        heading: false,
        codeBlock: false,
        blockquote: false,
        horizontalRule: false,
        hardBreak: false,
        orderedList: { HTMLAttributes: { class: 'list-decimal list-outside pl-5' } },
        bulletList: { HTMLAttributes: { class: 'list-disc list-outside pl-5' } },
      }),
      Underline,
      ListKeymap,
      Placeholder.configure({ placeholder: '• Achieved X by doing Y...' }),
    ],
    content: html,
    editorProps: {
      attributes: {
        class: 'prose prose-sm max-w-none focus:outline-none p-4 min-h-[200px] text-gray-700 leading-relaxed',
      },
    },
    onUpdate: ({ editor }) => onUpdate(editor.getHTML()),
  });

  useEffect(() => {
    if (editor && !editor.isDestroyed && editor.getHTML() !== html) {
      editor.commands.setContent(html, { emitUpdate: false });
    }
  }, [html, editor]);

  if (!editor) return null;

  return (
    <div className="border border-border rounded-xl bg-white overflow-hidden shadow-sm focus-within:border-primary focus-within:ring-2 focus-within:ring-primary/20 transition-all">
      <div className="flex items-center gap-1 px-3 py-2 bg-gray-50 border-b border-border flex-wrap">
        {[
            { action: () => editor.chain().focus().toggleBold().run(), name: 'bold', icon: <BoldIcon className="w-4 h-4" /> },
            { action: () => editor.chain().focus().toggleItalic().run(), name: 'italic', icon: <ItalicIcon className="w-4 h-4" /> },
            { action: () => editor.chain().focus().toggleUnderline().run(), name: 'underline', icon: <UnderlineIcon className="w-4 h-4" /> },
            { action: () => editor.chain().focus().toggleBulletList().run(), name: 'bulletList', icon: <ListBulletIcon className="w-4 h-4" /> },
            { action: () => editor.chain().focus().toggleOrderedList().run(), name: 'orderedList', icon: <ListNumberedIcon className="w-4 h-4" /> },
        ].map(({ action, name, icon }) => (
             <button key={name} type="button" onClick={action} className={`p-1.5 rounded-md hover:bg-gray-200 text-gray-600 transition-colors ${editor.isActive(name) ? 'bg-gray-300 text-gray-900' : ''}`} title={name}>
                {icon}
            </button>
        ))}
      </div>
      <EditorContent editor={editor} />
    </div>
  );
});

const InputGroup: React.FC<{
    label: string;
    icon: string;
    id: string;
    children: React.ReactNode;
    fullWidth?: boolean;
}> = ({ label, icon, id, children, fullWidth }) => (
    <div className={fullWidth ? 'col-span-full' : ''}>
        <label htmlFor={id} className="block text-sm font-semibold text-gray-700 mb-1.5 ml-1">{label}</label>
        <div className="relative group">
            <div className="absolute inset-y-0 left-0 pl-3.5 flex items-center pointer-events-none">
                <span className="material-symbols-outlined text-gray-400 group-focus-within:text-primary transition-colors text-[20px]">{icon}</span>
            </div>
            {children}
        </div>
    </div>
);

const ExperienceForm: React.FC<ExperienceFormProps> = ({ data, onAdd, onRemove, onClear, onNext, onFormDataChange }) => {
  const [activeId, setActiveId] = useState<string | null>(null);
  const [suggestions, setSuggestions] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [search, setSearch] = useState('');

  const activeExperience = useMemo(() => data.find(e => e.id === activeId), [data, activeId]);
  const isCurrent = activeExperience?.endDate === 'Present';

  useEffect(() => {
    if (data.length > 0 && (!activeId || !data.find(d => d.id === activeId))) {
      setActiveId(data[0].id);
    } else if (data.length === 0) {
      setActiveId(null);
    }
  }, [data, activeId]);

  useEffect(() => {
    if (!activeExperience?.jobTitle) {
      setSuggestions([]);
      return;
    }
    const timer = setTimeout(() => {
      setLoading(true);
      generateBulletPointSuggestions(activeExperience.jobTitle)
        .then(setSuggestions)
        .finally(() => setLoading(false));
    }, 500);
    return () => clearTimeout(timer);
  }, [activeExperience?.jobTitle]);

  const handleFieldChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!activeExperience) return;
    const { name, value } = e.target;
    onFormDataChange(prev => ({
      ...prev,
      experience: prev.experience.map(exp =>
        exp.id === activeId ? { ...exp, [name]: value } : exp
      ),
    }));
  };

   const handleCurrentWorkChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!activeExperience) return;
    const isChecked = e.target.checked;
    onFormDataChange(prev => ({
        ...prev,
        experience: prev.experience.map(exp =>
            exp.id === activeId ? { ...exp, endDate: isChecked ? 'Present' : '' } : exp
        ),
    }));
  };

  const handleDescriptionChange = (html: string) => {
    if (!activeExperience) return;
     onFormDataChange(prev => ({
      ...prev,
      experience: prev.experience.map(exp =>
        exp.id === activeId ? { ...exp, description: html } : exp
      ),
    }));
  };

  const currentDescriptionText = useMemo(() => {
      const div = document.createElement('div');
      div.innerHTML = activeExperience?.description || '';
      return div.textContent || '';
  }, [activeExperience?.description]);

  const availableSuggestions = useMemo(() => {
    return suggestions
      .filter(s => !currentDescriptionText.includes(s))
      .filter(s => s.toLowerCase().includes(search.toLowerCase()));
  }, [suggestions, currentDescriptionText, search]);

  const addSuggestion = (text: string) => {
    const currentHtml = activeExperience?.description || '';
    const newBullet = `<li>${text}</li>`;
    let newHtml;

    if (currentHtml.includes('<ul>')) {
        newHtml = currentHtml.replace('</ul>', `${newBullet}</ul>`);
    } else if (currentHtml.includes('<ol>')) {
        newHtml = currentHtml.replace('</ol>', `${newBullet}</ul>`);
    } else {
        newHtml = `${currentHtml}<ul>${newBullet}</ul>`;
    }
    handleDescriptionChange(newHtml);
  };

  return (
    <>
        <ContentHeader
            title="Work Experience"
            description="Detail your professional roles. We recommend listing your 3-4 most relevant positions."
        />

        {/* Horizontal Card Navigation */}
        <div className="mb-8 overflow-x-auto pb-4 -mx-2 px-2 flex gap-4 snap-x no-scrollbar">
            {data.map((exp, index) => (
                <button
                    key={exp.id}
                    type="button"
                    onClick={() => setActiveId(exp.id)}
                    className={`snap-start flex-shrink-0 w-[240px] text-left p-4 rounded-xl border transition-all duration-200 group relative overflow-hidden ${
                        activeId === exp.id 
                        ? 'bg-white border-primary shadow-md ring-1 ring-primary' 
                        : 'bg-white border-border hover:border-primary/50 hover:shadow-sm'
                    }`}
                >
                     {activeId === exp.id && <div className="absolute top-0 left-0 w-1 h-full bg-primary"></div>}
                    <div className="flex items-start justify-between mb-2">
                        <div className={`p-2 rounded-lg ${activeId === exp.id ? 'bg-primary/10 text-primary' : 'bg-gray-100 text-gray-500'}`}>
                             <span className="material-symbols-outlined text-[20px]">work</span>
                        </div>
                        <span className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">Job {index + 1}</span>
                    </div>
                    <h3 className={`font-bold text-sm truncate mb-0.5 ${activeId === exp.id ? 'text-dark' : 'text-gray-700'}`}>
                        {exp.jobTitle || 'Untitled Role'}
                    </h3>
                    <p className="text-xs text-gray-500 truncate mb-2">{exp.company || 'No Company'}</p>
                    <p className="text-[11px] font-medium text-gray-400 flex items-center gap-1">
                         <span className="material-symbols-outlined text-[12px]">calendar_month</span>
                        {exp.startDate || 'Start'} - {exp.endDate || 'End'}
                    </p>
                </button>
            ))}

            <button
                type="button"
                onClick={() => { onAdd(); }}
                className="snap-start flex-shrink-0 w-[100px] flex flex-col items-center justify-center gap-2 rounded-xl border-2 border-dashed border-border hover:border-primary hover:bg-primary-light/10 transition-all text-gray-400 hover:text-primary"
            >
                <span className="material-symbols-outlined text-3xl">add_circle</span>
                <span className="text-xs font-bold">Add New</span>
            </button>
        </div>

        {activeExperience ? (
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 animate-fade-in">
                {/* Main Form Area */}
                <div className="lg:col-span-7 space-y-6">
                    <div className="bg-white p-6 rounded-2xl border border-border shadow-sm space-y-6">
                         <div className="flex justify-between items-center border-b border-border pb-4">
                            <h3 className="text-lg font-bold text-dark flex items-center gap-2">
                                <span className="material-symbols-outlined text-primary">edit_note</span>
                                Edit Details
                            </h3>
                            <button 
                                type="button" 
                                onClick={() => onRemove(activeExperience.id)} 
                                className="text-sm font-medium text-danger hover:bg-red-50 px-3 py-1.5 rounded-lg transition-colors flex items-center gap-1"
                            >
                                <span className="material-symbols-outlined text-[18px]">delete</span>
                                Delete
                            </button>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                            <InputGroup label="Job Title" icon="badge" id={`jobTitle-${activeExperience.id}`} fullWidth>
                                <input 
                                    type="text" 
                                    id={`jobTitle-${activeExperience.id}`} 
                                    name="jobTitle" 
                                    value={activeExperience.jobTitle} 
                                    onChange={handleFieldChange} 
                                    placeholder="e.g. Senior Product Manager" 
                                    className="w-full pl-10 pr-4 py-3 border border-border rounded-xl text-base focus:outline-none focus:border-primary focus:ring-2 focus:ring-primary/20 transition-all" 
                                />
                            </InputGroup>

                            <InputGroup label="Company" icon="business" id={`company-${activeExperience.id}`}>
                                <input 
                                    type="text" 
                                    id={`company-${activeExperience.id}`} 
                                    name="company" 
                                    value={activeExperience.company} 
                                    onChange={handleFieldChange} 
                                    placeholder="e.g. Google" 
                                    className="w-full pl-10 pr-4 py-3 border border-border rounded-xl text-base focus:outline-none focus:border-primary focus:ring-2 focus:ring-primary/20 transition-all" 
                                />
                            </InputGroup>

                            <InputGroup label="Location" icon="location_on" id={`location-${activeExperience.id}`}>
                                <input 
                                    type="text" 
                                    id={`location-${activeExperience.id}`} 
                                    name="location" 
                                    value={activeExperience.location} 
                                    onChange={handleFieldChange} 
                                    placeholder="e.g. New York, NY" 
                                    className="w-full pl-10 pr-4 py-3 border border-border rounded-xl text-base focus:outline-none focus:border-primary focus:ring-2 focus:ring-primary/20 transition-all" 
                                />
                            </InputGroup>

                            <InputGroup label="Start Date" icon="calendar_today" id={`startDate-${activeExperience.id}`}>
                                <input 
                                    type="text" 
                                    id={`startDate-${activeExperience.id}`} 
                                    name="startDate" 
                                    value={activeExperience.startDate} 
                                    onChange={handleFieldChange} 
                                    placeholder="e.g. January 2020"
                                    className="w-full pl-10 pr-4 py-3 border border-border rounded-xl text-base focus:outline-none focus:border-primary focus:ring-2 focus:ring-primary/20 transition-all bg-white" 
                                />
                            </InputGroup>

                            <div className="relative">
                                <InputGroup label="End Date" icon="event" id={`endDate-${activeExperience.id}`}>
                                    <input 
                                        type="text" 
                                        id={`endDate-${activeExperience.id}`}
                                        name="endDate" 
                                        value={isCurrent ? '' : activeExperience.endDate} 
                                        onChange={handleFieldChange} 
                                        disabled={isCurrent}
                                        placeholder="e.g. Present"
                                        className="w-full pl-10 pr-4 py-3 border border-border rounded-xl text-base focus:outline-none focus:border-primary focus:ring-2 focus:ring-primary/20 transition-all bg-white disabled:bg-gray-100 disabled:text-gray-400" 
                                    />
                                </InputGroup>
                                <div className="absolute top-0 right-0 pt-1 pr-1">
                                     <label className="inline-flex items-center cursor-pointer bg-gray-100 px-3 py-1 rounded-full border border-border hover:bg-gray-200 transition-colors">
                                        <input 
                                            type="checkbox" 
                                            className="form-checkbox h-4 w-4 text-primary rounded border-gray-300 focus:ring-primary"
                                            checked={!!isCurrent}
                                            onChange={handleCurrentWorkChange}
                                        />
                                        <span className="ml-2 text-xs font-semibold text-gray-600 select-none">Current Role</span>
                                    </label>
                                </div>
                            </div>
                        </div>

                        <div>
                             <label className="flex items-center justify-between text-sm font-semibold text-gray-700 mb-2 ml-1">
                                <span>Achievements & Responsibilities</span>
                                <span className="text-xs font-normal text-gray-500">Use bullet points for clarity</span>
                             </label>
                             <BulletEditor html={activeExperience.description} onUpdate={handleDescriptionChange} />
                        </div>
                    </div>
                </div>

                {/* AI Suggestions Sidebar */}
                <div className="lg:col-span-5 h-full">
                    <div className="bg-gradient-to-br from-blue-50 to-indigo-50 p-1 rounded-2xl border border-secondary/20 h-full flex flex-col shadow-sm">
                        <div className="p-4 flex items-center gap-2 border-b border-secondary/10 bg-white/50 rounded-t-xl">
                            <SparklesIcon />
                            <h4 className="font-bold text-secondary text-sm">AI Suggestions</h4>
                        </div>

                        <div className="p-4 flex-1 flex flex-col min-h-[400px]">
                            <div className="relative mb-4">
                                <input
