                            className="h-4 w-4 text-primary focus:ring-primary border-gray-300 rounded"
                        />
                        <label htmlFor={`current-${item.id}`} className="ml-2 block text-sm text-gray-900">
                            {isExperience ? 'I currently work here' : 'I currently study here'}
                        </label>
                    </div>
                </div>
                <div className="col-span-2">
                    <label className="font-semibold mb-2 block text-sm text-gray-700">Location</label>
                    <input type="text" className="w-full p-3 border border-border rounded-lg bg-white" name="location" placeholder="e.g., New York, NY" value={item.location} onChange={handleChange} />
                </div>
                <div className="col-span-2">
                    <label className="font-semibold text-sm text-gray-700 mb-2 block">{isExperience ? 'Job Description' : 'Details'}</label>
                    <textarea
                        className="w-full p-3 border border-border rounded-lg bg-white min-h-[120px] resize-y"
